def calculate_next_term(x_i, x_i_minus_1):
    # x_{i+1} = (x_i^2 - x_{i-1}) / (x_{i-1} + 1)
    numerator = x_i**2 - x_i_minus_1
    denominator = x_i_minus_1 + 1

    if denominator == 0:
        return None # Should not happen since x_i_minus_1 >= 1

    if numerator % denominator != 0:
        return None # Not an integer

    x_i_plus_1 = numerator // denominator

    # Must be a positive integer
    if x_i_plus_1 <= 0:
        return None

    return x_i_plus_1

def find_sequence_length(x1, x2):
    sequence = [x1, x2]

    while True:
        x_i = sequence[-1]
        x_i_minus_1 = sequence[-2]

        x_next = calculate_next_term(x_i, x_i_minus_1)

        if x_next is None:
            # Sequence terminated (not an integer or not positive)
            break

        sequence.append(x_next)

    return sequence, len(sequence)

# Search limit
LIMIT = 15

max_n = 0
longest_sequences = {}

print("Starting systematic search up to x1, x2 <= 15...")

for x1 in range(1, LIMIT + 1):
